            .join('');

          const formattedUuid = `${receivedUuid.slice(0, 8)}-${receivedUuid.slice(8, 12)}-${receivedUuid.slice(12, 16)}-${receivedUuid.slice(16, 20)}-${receivedUuid.slice(20)}`;

