            isAuthorized = true;
            const responseHeader = new Uint8Array([version, 0]);
            server.send(responseHeader);
          } else {
            server.close();
          }
          return;
        }
      } catch (err) {
        server.close();
      }
    });

    return new Response(null, {
      status: 101,
      webSocket: client,
    });
  },
};
